files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #171819;
  --vt-ink: #171819;
  --vt-ink-soft: #666262;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6300a;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #d6300a;
  --vt-accent-on-deep: #ff6b4a;
  --vt-line: #444444;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  box-sizing: border-box;
}

.root,
.root * {
  box-sizing: border-box;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent-on-deep);
  outline-offset: 2px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface-deep);
  padding: 1rem 0;
  z-index: 100;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  text-decoration: none;
  font-size: 1.75rem;
  font-weight: bold;
  color: var(--vt-on-deep);
}

.brand {
  color: inherit;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.navLinks a {
  color: var(--vt-on-deep);
  text-decoration: none;
  text-transform: uppercase;
  font-size: 0.875rem;
  padding: 0.25rem 0.5rem;
  transition: color 0.3s ease;
}

.navLinks a:hover {
  color: var(--vt-accent-on-deep);
}

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.heroBg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: top;
  background-repeat: no-repeat;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.85;
}

.heroInner {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: 0 15px;
}

.heroKicker {
  color: var(--vt-accent-on-deep);
  font-size: 1.375rem;
  margin: 0;
  text-transform: uppercase;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: 3rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: -1px;
  margin: 20px 0;
}

.heroCtas {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.5rem;
  flex-wrap: wrap;
}

.btn {
  display: inline-block;
  padding: 14px 24px;
  border-radius: 2px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-decoration: none;
  transition: all 0.3s ease;
  border: 1px solid transparent;
  cursor: pointer;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.btnPrimary:hover {
  background: var(--vt-on-accent);
  color: var(--vt-accent);
}

.btnOutline {
  background: transparent;
  color: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
}

.btnOutline:hover {
  background: var(--vt-accent-on-deep);
  color: var(--vt-surface-deep);
}

.feature {
  background: var(--vt-surface-deep);
  padding: 5rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.featureGrid {
  display: grid;
  grid-template-columns: 5fr 4fr;
  gap: 2rem;
  align-items: center;
}

.headingLight {
  color: var(--vt-on-deep);
  font-size: 2.25rem;
  font-weight: bold;
  letter-spacing: -2px;
  margin-bottom: 1rem;
}

.paragraphLight {
  color: var(--vt-on-deep);
  font-size: 1.125rem;
  line-height: 1.5;
  margin-bottom: 1.5rem;
}

.hoursCard {
  border-left: 2px solid var(--vt-accent-on-deep);
  padding-left: 2rem;
}

.hoursText {
  color: var(--vt-on-deep);
  font-size: 1.125rem;
  line-height: 1.6;
  white-space: pre-line;
}

.about {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.headingDark {
  color: var(--vt-ink);
  font-size: 2.25rem;
  font-weight: bold;
  letter-spacing: -2px;
  margin-bottom: 1rem;
}

.paragraphDark {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  line-height: 1.5;
  margin-bottom: 1rem;
}

.aboutImageWrapper {
  border-radius: 2px;
  overflow: hidden;
}

.aboutImage {
  width: 100%;
  height: auto;
  display: block;
}

.classes {
  background: var(--vt-surface);
  padding: 7rem 0;
}

.sectionHeader {
  text-align: center;
  margin-bottom: 3rem;
}

.sectionKicker {
  color: var(--vt-ink-soft);
  font-size: 1.375rem;
  text-transform: uppercase;
  margin: 0;
}

.classGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.classCard {
  background: var(--vt-surface);
  border-radius: 2px;
  box-shadow: 0 0 0 1px var(--vt-line);
  overflow: hidden;
}

.classImageWrap {
  border-radius: 2px 2px 0 0;
  overflow: hidden;
}

.classImage {
  width: 100%;
  height: auto;
  display: block;
}

.classInfo {
  background: var(--vt-surface);
  padding: 1rem 2rem;
  position: relative;
}

.classTitle {
  color: var(--vt-ink);
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.classDesc {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.5;
  margin-bottom: 0.5rem;
}

.classPrice {
  position: absolute;
  top: 1rem;
  right: 2rem;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 50%;
  width: 3.5rem;
  height: 3.5rem;
  line-height: 3.5rem;
  text-align: center;
  font-weight: bold;
}

.classDuration {
  display: block;
  color: var(--vt-ink-soft);
  font-size: 0.875rem;
  margin-top: 0.5rem;
}

.contact {
  background: var(--vt-surface);
  padding: 7rem 0;
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.formInput,
.formTextarea {
  width: 100%;
  padding: 10px 15px;
  border: 1px solid var(--vt-line);
  border-radius: 2px;
  font-size: 1rem;
  color: var(--vt-ink);
  background: var(--vt-surface);
}

.formInput {
  height: 50px;
}

.formTextarea {
  resize: vertical;
}

.formSubmit {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  border: none;
  padding: 14px 24px;
  border-radius: 2px;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.3s ease;
}

.formSubmit:hover {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.socialLinks {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
}

.footer {
  border-top: 1px solid var(--vt-surface-2);
  background: var(--vt-surface);
  padding: 3rem 0;
  text-align: center;
}

.footerText {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  line-height: 1.5;
  margin: 0.25rem 0;
}

@media (max-width: 992px) {
  .section,
  .about,
  .classes,
  .contact {
    padding: 5rem 0;
  }

  .featureGrid,
  .aboutGrid,
  .contactGrid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .classGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .heroTitle {
    font-size: 2.5rem;
  }
}

@media (max-width: 767px) {
  .heroTitle {
    font-size: 2.375rem;
  }

  .classGrid {
    grid-template-columns: 1fr;
  }

  .navIn {
    flex-direction: column;
    gap: 1rem;
  }

  .hoursCard {
    border-left: 0;
    padding-left: 0;
    padding-top: 1rem;
  }
}
